      "title": "'রিফাত এন্টারপ্রাইজ' (ব্যবসায়িক লেনদেন চিহ্নিতকরণ ও হিসাব সমীকরণ)",
      "stem": "'রিফাত এন্টারপ্রাইজ' একটি ব্যবসায় প্রতিষ্ঠান। ২০২৫ সালের ডিসেম্বর মাসে উক্ত ব্যবসায় প্রতিষ্ঠানে নিম্নোক্ত ঘটনাগুলো সংঘটিত হয়েছে :\n\n- **ডিসেম্বর ১:** ৫,০০,০০০ টাকা নিয়ে ব্যবসায় শুরু করা হলো।\n- **ডিসেম্বর ৩:** ব্যাংকে ৫০,০০০ টাকা জমা দিয়ে একটি হিসাব খোলা হলো।\n- **ডিসেম্বর ৫:** ধারে পণ্য ক্রয় ২৫,০০০ টাকা।\n- **ডিসেম্বর ১০:** মালিক কর্তৃক ব্যাংক হতে ব্যক্তিগত প্রয়োজনে ঋণ গ্রহণ ৪০,০০০ টাকা।\n- **ডিসেম্বর ১৫:** ৪৫,০০০ টাকার আসবাবপত্র ক্রয়ের ফরমায়েশ প্রদান।\n- **ডিসেম্বর ২০:** প্রদেয় হিসাব পরিশোধ ১৫,০০০ টাকা।",
      "ka": "উপর্যুক্ত তথ্য হতে ব্যবসায়িক লেনদেন নয় এমন ঘটনাসমূহ চিহ্নিত করে মোট পরিমাণ নির্ণয় করো।",
      "kha": "ঘটনাসমূহ হতে লেনদেন চিহ্নিত করে সমীকরণ পদ্ধতিতে তার কারণ ব্যাখ্যা করো।",
      "ga": "হিসাব সমীকরণের উপর লেনদেনের প্রভাব (A = L + OE) বিবরণী ছকে দেখাও।",
      "solution": {
        "ka": "**ব্যবসায়িক লেনদেন নয় এমন ঘটনার পরিমাণ:**\n1. ডিসেম্বর ১০: মালিকের ব্যক্তিগত প্রয়োজনে ব্যাংক ঋণ গ্রহণ = ৪০,০০০ টাকা (এটি মালিকের ব্যক্তিগত ঋণ, ব্যবসায়ের আর্থিক অবস্থা প্রভাবিত করে না)।\n2. ডিসেম্বর ১৫: আসবাবপত্র ক্রয়ের ফরমায়েশ প্রদান = ৪৫,০০০ টাকা (শুধুমাত্র ক্রয়ের অর্ডার দেওয়া হয়েছে, নগদ বা পণ্যের কোনো আদান-প্রদান ঘটেনি)।\n\n**মোট লেনদেন নয় এমন ঘটনার পরিমাণ:** ৪০,০০০ + ৪৫,০০০ = **৮৫,০০০ টাকা** (বা শুধুমাত্র আনুষ্ঠানিক ফরমায়েশ বিবেচনায় ৪৫,০০০ টাকা)।",
        "kha": "**সমীকরণ পদ্ধতিতে লেনদেনের কারণ ব্যাখ্যা:**\n- **ডিসে ১ (লেনদেন):** ব্যবসায়ে নগদ টাকা আসার ফলে নগদ সম্পদ (A) বৃদ্ধি এবং মালিকের মূলধন বা মালিকানাস্বত্ব (OE) বৃদ্ধি পেয়েছে।\n- **ডিসে ৩ (লেনদেন):** ব্যাংকে টাকা জমার ফলে ব্যাংক সম্পদ (A) বৃদ্ধি এবং নগদ সম্পদ (A) হ্রাস পেয়েছে।\n- **ডিসে ৫ (লেনদেন):** ধারে ক্রয়ের ফলে ব্যয় বৃদ্ধির কারণে মালিকানাস্বত্ব (OE) হ্রাস এবং প্রদেয় হিসাব দায় (L) বৃদ্ধি পেয়েছে।\n- **ডিসে ১০ (লেনদেন নয়):** ব্যবসায়ের সম্পদ, দায় বা মালিকানাস্বত্বের কোনো পরিবর্তন ঘটেনি।\n- **ডিসে ১৫ (লেনদেন নয়):** কোনো আর্থিক লেনদেন বা সম্পদের বিনিময় ঘটেনি।\n- **ডিসে ২০ (লেনদেন):** প্রদেয় অর্থ পরিশোধ করায় নগদ সম্পদ (A) হ্রাস এবং প্রদেয় দায় (L) হ্রাস পেয়েছে।",
        "ga": "**হিসাব সমীকরণে লেনদেনের প্রভাব ছক:**\n- সম্পদ (নগদ ৫,০০,০০০ - ৫০,০০০ - ১৫,০০০ = ৪,৩৫,০০০ + ব্যাংক ৫০,০০০) = **৪,৮৫,০০০ টাকা**।\n- দায় ও মালিকানাস্বত্ব (প্রদেয় হিসাব ১০,০০০ + সমাপনী মূলধন ৪,৭৫,০০০) = **৪,৮৫,০০০ টাকা**।\n\nউভয় দিকে মোট পরিমাণ ৪,৮৫,০০০ টাকা সমান।"
      }
