      "stem": "'লিগ্যাল এইড' নামে জনাব আসফিয়া ২ মে ২০২৫ তারিখে তার আইন ব্যবসায় চালু করেন। প্রথম মাসের ঘটনাগুলো নিম্নরূপ :\n\n- **মে ২:** আইন পেশায় ১,০০,০০০ টাকা বিনিয়োগ করা হলো।\n- **মে ৪:** অফিস ভাড়া পরিশোধ করা হলো ১৮,০০০ টাকা।\n- **মে ৮:** ধারে সেবা সরঞ্জাম ক্রয় করা হলো ৪০,০০০ টাকা।\n- **মে ১২:** মক্কেলদের নগদে আইনি সেবা দেওয়া হলো ৯০,০০০ টাকা।\n- **মে ১৬:** অফিস কর্মচারীর বেতন পরিশোধ ১০,০০০ টাকা।\n- **মে ২৫:** ব্যাংক থেকে ঋণ নেওয়া হলো ১,০০,০০০ টাকা।\n- **মে ২৭:** মক্কেলদের ধারে আইনি সেবা দেওয়া হলো ৬০,০০০ টাকা।\n- **মে ৩০:** বাকিতে ক্রীত সেবা সরঞ্জামের মূল্য পরিশোধ ৩০,০০০ টাকা।",
