        "kha": "**A = L + OE প্রমাণ ছক:**\n- জানু ১: নগদ +১,২০,০০০, আসবাবপত্র +৭০,০০০ = মূলধন +১,৯০,০০০\n- জানু ২: নগদ -৫০,০০০, ব্যাংক +৫০,০০০ = ০\n- জানু ৪: পণ্য ক্রয় ব্যয় -৪৫,০০০ (OE হ্রাস), নগদ -২০,০০০, ব্যাংক -১৫,০০০, প্রদেয় হিসাব +১০,০০০\n- জানু ৯: নগদ -১০,০০০, প্রদেয় হিসাব -১০,০০০\nপ্রতিটি পর্যায়ে মোট সম্পদ = দায় + মালিকানাস্বত্ব বজায় থাকে।",
