      "stem": "২০২৫ সালের জানুয়ারি মাসের ১ তারিখে জনাব জহির একটি গাড়ি মেরামতের 'জহির ওয়ার্কশপ' নামে ব্যবসায় শুরু করেন। তার প্রতিষ্ঠানে নিম্নের লেনদেনগুলো সংঘটিত হয় :\n\n- **জানুয়ারি ১:** জনাব জহির নগদ ৫,০০,০০০ টাকা ও ৫০,০০০ টাকার আসবাবপত্র ব্যবসায়ে বিনিয়োগ করেন।\n- **জানুয়ারি ১৬:** প্রতিষ্ঠানে ব্যবহার করার জন্য ৬৫,০০০ টাকা দিয়ে যন্ত্রপাতি ক্রয় করেন।\n- **জানুয়ারি ২১:** গাড়ি মেরামত করে ৮০,০০০ টাকা আয় করেন।\n- **জানুয়ারি ২৬:** ওয়ার্কশপের ভাড়া প্রদান ২১,০০০ টাকা।\n- **জানুয়ারি ২৮:** প্রতিষ্ঠানের কর্মচারীদের বেতন প্রদান করেন ২৫,০০০ টাকা।\n- **জানুয়ারি ৩০:** মালিকের গাড়ি মেরামত ১৫,০০০ টাকা।",
