        "ga": "**হিসাব সমীকরণে প্রভাব:**\n- জানু ১: নগদ (A) বৃদ্ধি ৫,০০,০০০, আসবাবপত্র (A) বৃদ্ধি ৫০,০০০, মূলধন (OE) বৃদ্ধি ৫,৫০,০০০।\n- জানু ১৬: যন্ত্রপাতি (A) বৃদ্ধি ৬৫,০০০, নগদ (A) হ্রাস ৬৫,০০০।\n- জানু ২৮: নগদ (A) হ্রাস ২৫,০০০, মালিকানাস্বত্ব (OE) হ্রাস ২৫,০০০ (বেতন খরচ)।\n- জানু ৩০: মালিকানাস্বত্ব বা সেবা আয় (OE) বৃদ্ধি ১৫,০০০ এবং উত্তোলন (OE) হ্রাস ১৫,০০০। নিট প্রভাব ০।"
