        "kha": "**কারণসহ ডেবিট ও ক্রেডিট:**\n- **মে ২:** অফিস সরঞ্জাম ডেবিট ৩০,০০০ টাকা (সম্পদ বৃদ্ধি); নগদান হিসাব ক্রেডিট ৩০,০০০ টাকা (সম্পদ হ্রাস)।\n- **মে ৮:** প্রাপ্য হিসাব ডেবিট ৪০,০০০ টাকা (সম্পদ বৃদ্ধি); বিক্রয় হিসাব ক্রেডিট ৪০,০০০ টাকা (মালিকানাস্বত্ব/আয় বৃদ্ধি)।\n- **মে ১৫:** ব্যাংক হিসাব ডেবিট ১০,০০০ টাকা (সম্পদ বৃদ্ধি); নগদান হিসাব ক্রেডিট ১০,০০০ টাকা (সম্পদ হ্রাস)।\n- **মে ২২:** বিদ্যুৎ বিল হিসাব ডেবিট ২,০০০ টাকা (ব্যয় বৃদ্ধি); বকেয়া বিদ্যুৎ বিল হিসাব ক্রেডিট ২,০০০ টাকা (দায় বৃদ্ধি)।\n- **মে ২৮:** ব্যাংক হিসাব ডেবিট ২৫,০০০ টাকা (সম্পদ বৃদ্ধি); প্রাপ্য হিসাব ক্রেডিট ২৫,০০০ টাকা (সম্পদ হ্রাস)।",
        "ga": "**উপাদানভিত্তিক পরিবর্তন:**\n- মে ২: A (+৩০,০০০) এবং A (-৩০,০০০)।\n- মে ৮: A (+৪০,০০০) এবং OE (+৪০,০০০)।\n- মে ১৫: A (+১০,০০০) এবং A (-১০,০০০)।\n- মে ২২: L (+২,০০০) এবং OE (-২,০০০)।\n- মে ২৮: A (+২৫,০০০) এবং A (-২৫,০০০)।\nউভয় দিকে মোট সম্পদের পরিবর্তন ও দায়-মালিকানাস্বত্বের পরিবর্তন সবসময় ভারসাম্যপূর্ণ থাকে।"
