      "stem": "'মেসার্স ডেল্টা মিলস'-এর ২০২৪ সালের লেনদেনসমূহ:\n- নতুন পণ্য তৈরির পূর্বে ব্যাপক গবেষণা ও উন্নয়ন ব্যয় ৬০,০০০ টাকা যা আগামী ৪ বছরব্যাপী সুবিধা দেবে।\n- ব্যবসায়ের নতুন শোরুম স্থানান্তর ব্যয় ২০,০০০ টাকা।\n- কারখানার বিদ্যুৎ বিল পরিশোধ ৮,০০০ টাকা।\n- ৫ বছরের জন্য এককালীন পণ্যের বিশেষ প্রচার ও বিজ্ঞাপন বাবদ প্রদান ৫০,০০০ টাকা।\n- যন্ত্রপাতির বার্ষিক মেরামত খরচ ৫,০০০ টাকা।",
