      "stem": "'মেঘনা টেক্সটাইলস' ২০২৪ সালে জার্মানি থেকে ৩,০০,০০০ টাকার একটি সুতা তৈরির মেশিন ক্রয় করে। মেশিনটি আনতে জাহাজভাড়া ২০,০০০ টাকা, শুল্ক ১৫,০০০ টাকা এবং কারখানা সংস্থাপন বাবদ মজুরি প্রদান ১০,০০০ টাকা। মেশিন চালুর পর প্রথম মাসে তৈল ও লুব্রিকেন্ট ক্রয় ৩,০০০ টাকা এবং ত্রৈমাসিক সার্ভিসিং চার্জ ২,০০০ টাকা খরচ হয়।",
