      "stem": "'শাহজাহান স্টোর'-এর স্বত্বাধিকারী লক্ষ্য করলেন যে, বছর শেষে তার মূলধনের পরিমাণ প্রারম্ভিক মূলধনের চেয়ে অনেক বৃদ্ধি পেয়েছে। হিসাব পর্যালোচনায় দেখা গেল, বছরে বিক্রয় আয় ৩,০০,০০০ টাকা, বেতন ব্যয় ৬০,০০০ টাকা, ভাড়া ব্যয় ৪০,০০০ টাকা এবং ব্যক্তিগত উত্তোলন ২০,০০০ টাকা।",
