      "stem": "'মেসার্স রুমি এন্টারপ্রাইজ' একটি কাপড়ের ব্যবসা। ২০২৪ সালের এপ্রিল মাসে তাদের ধারে ক্রয় সংক্রান্ত তথ্যসমূহ:\n- **এপ্রিল ৩:** মেসার্স সুমনা টেক্সটাইল হতে প্রতি থান ৫০০ টাকা দরে ১০০ থান সুতি শাড়ি ক্রয়। কারবারি বাট্টা ১০%। চালান নং ২০১, শর্ত: ২/১০, নিট ৩০।\n- **এপ্রিল ১২:** মেসার্স রাজু ফেব্রিক্স হতে প্রতি গজ ৮০ টাকা দরে ৫০০ গজ থান কাপড় ক্রয়। চালান নং ২০৫, বাট্টা ৫%, প্যাকিং খরচ ৫০০ টাকা।\n- **এপ্রিল ১৮:** পুরাতন আসবাবপত্র ক্রয় ১০,০০০ টাকা।",
