      "stem": "'সুরভী কসমেটিক্স'-এর ২০২৪ সালের সেপ্টেম্বর মাসের কিছু লেনদেন:\n- **সেপ্টেম্বর ১:** ব্যাংক জমার উদ্বৃত্ত ৮০,০০০ টাকা।\n- **সেপ্টেম্বর ৬:** মেসার্স নিপা ট্রেডার্স হতে ধারে কসমেটিক্স ক্রয় ২৫,০০০ টাকা।\n- **সেপ্টেম্বর ১৪:** দেনাদার হতে প্রাপ্ত চেক ব্যাংকে জমা ২০,০০০ টাকা।\n- **সেপ্টেম্বর ২২:** নিপা ট্রেডার্সকে চেক মারফত পরিশোধ ১৫,০০০ টাকা।\n- **সেপ্টেম্বর ২৮:** ব্যাংক কর্তৃক সুদ মঞ্জুর ৫০০ টাকা।",
      "ka": "খতিয়ানের হিসাব কোড নম্বর ব্যবহারের সুবিধা কী?",
      "kha": "চলমান জের ছকে 'ব্যাংক হিসাব' প্রস্তুত করো।",
      "ga": "চলমান জের ছকে 'প্রদেয় হিসাব-নিপা ট্রেডার্স' প্রস্তুত করো।",
      "solution": {
        "ka": "হিসাব কোড নম্বর ব্যবহার করলে খতিয়ানের পাতা দ্রুত খুঁজে পাওয়া যায় এবং কম্পিউটারাইজড হিসাব সংরক্ষণে অত্যন্ত নির্ভুল ও দ্রুততম সময়ে তথ্য প্রক্রিয়াজাত করা যায়।",
        "kha": "**ব্যাংক হিসাব (চলমান জের ছক):**\n- সেপ্টে ১ | ব্যালেন্স | ডেবিট ৮০,০০০ টাকা\n- সেপ্টে ১৪ | প্রাপ্য হিসাব | ডেবিট ২০,০০০ টাকা ➔ ডেবিট জের ১,০০,০০০ টাকা\n- সেপ্টে ২২ | প্রদেয় হিসাব (নিপা) | ক্রেডিট ১৫,০০০ টাকা ➔ ডেবিট জের ৮৫,০০০ টাকা\n- সেপ্টে ২৮ | ব্যাংক সুদ হিসাব | ডেবিট ৫০০ টাকা ➔ **সমাপনী ডেবিট জের ৮৫,৫০০ টাকা**।",
        "ga": "**প্রদেয় হিসাব - নিপা ট্রেডার্স (চলমান জের ছক):**\n- সেপ্টে ৬ | ক্রয় হিসাব | ক্রেডিট ২৫,০০০ টাকা ➔ ক্রেডিট জের ২৫,০০০ টাকা\n- সেপ্টে ২২ | ব্যাংক হিসাব | ডেবিট ১৫,০০০ টাকা ➔ **সমাপনী ক্রেডিট জের ১০,০০০ টাকা**।"
      }
