      "stem": "'যমুনা এন্টারপ্রাইজ'-এর ২০২৪ সালের অক্টোবর মাসের ধারে বিক্রয় সংক্রান্ত তথ্য:\n- **অক্টোবর ৩:** সোহেলের নিকট ধারে বিক্রয় ২০,০০০ টাকা।\n- **অক্টোবর ১০:** মামুনের নিকট ধারে বিক্রয় ৩৫,০০০ টাকা।\n- **অক্টোবর ১৮:** সোহেল ফেরত পাঠাল ২,০০০ টাকার পণ্য।\n- **অক্টোবর ২৫:** মামুনের নিকট হতে নগদ আদায় ২৫,০০০ টাকা।",
