      "stem": "'কর্ণফুলী ব্রাদার্স'-এর কতিপয় লেনদেন:\n১. প্রারম্ভিক হাতে নগদ ৫০,০০০ টাকা ও প্রদেয় হিসাব ২০,০০০ টাকা।\n২. ধারে পণ্য ক্রয় ৩০,০০০ টাকা।\n৩. পাওনাদারকে পরিশোধ ২৫,০০০ টাকা।\n৪. নগদে পণ্য বিক্রয় ৪০,০০০ টাকা।",
