        "ga": "**নগদান হিসাব (খতিয়ান):**\n- ব্যালেন্স বি/ডি (প্রারম্ভিক) = ডেবিট ৫০,০০০ টাকা\n- বিক্রয় হিসাব = ডেবিট ৪০,০০০ টাকা (মোট ডেবিট = ৯০,০০০ টাকা)\n- প্রদেয় হিসাব (পরিশোধ) = ক্রেডিট ২৫,০০০ টাকা\n**সমাপনী ডেবিট জের = ৬৫,০০০ টাকা**।"
