      "ka": "কন্ট্রা এন্ট্রি (বিপরীত দাখিলা)-র মোট পরিমাণ কত?",
      "kha": "উপযুক্ত তথ্যের ভিত্তিতে একটি তিনঘরা নগদান বই প্রস্তুত করো।",
