      "stem": "'শাপলা ট্রেডিং'-এর ২০২৪ সালের আগস্ট মাসের নগদ ও চেকে প্রাপ্তি সংক্রান্ত তথ্য:\n- **আগস্ট ২:** নগদ বিক্রয় ৫০,০০০ টাকা।\n- **আগস্ট ৮:** দেনাদার আশিকের নিকট হতে চেকে প্রাপ্তি ১৮,০০০ টাকা, বাট্টা মঞ্জুর ১,০০০ টাকা।\n- **আগস্ট ১৫:** অতিরিক্ত মূলধন আনা হলো ২০,০০০ টাকা।\n- **আগস্ট ২২:** পুরাতন আসবাবপত্র বিক্রয় ১০,০০০ টাকা।",
      "ka": "নগদ প্রাপ্তি জাবেদায় (Cash Receipts Journal) কয়টি টাকার ঘর থাকে?",
      "kha": "উদ্দীপক হতে আগস্ট মাসে মোট বাট্টা ও বিক্রয়ের পরিমাণ কত?",
      "ga": "উপযুক্ত তথ্যাবলি দিয়ে একটি নগদ প্রাপ্তি জাবেদা (CRJ) প্রস্তুত করো।",
      "solution": {
        "ka": "নগদ প্রাপ্তি জাবেদায় সাধারণত **৫টি টাকার ঘর** থাকে (নগদান ডেবিট, প্রদত্ত বাট্টা ডেবিট, বিক্রয় ক্রেডিট, প্রাপ্য হিসাব ক্রেডিট এবং অন্যান্য হিসাব ক্রেডিট)।",
        "kha": "**বাট্টা ও বিক্রয়ের পরিমাণ:**\n- প্রদত্ত বাট্টা = ১,০০০ টাকা।\n- বিক্রয় = ৫০,০০০ টাকা।",
        "ga": "**নগদ প্রাপ্তি জাবেদা (CRJ) | শাপলা ট্রেডিং:**\n(তারিখ | ক্রেডিট হিসাব খাত | সূত্র | নগদান ডে. | প্রদত্ত বাট্টা ডে. | বিক্রয় ক্রে. | প্রাপ্য হিসাব ক্রে. | অন্যান্য ক্রে.)\n1. আগস্ট ২ | বিক্রয় হিসাব | | ৫০,০০০ | - | ৫০,০০০ | - | -\n2. আগস্ট ৮ | আশিক | | ১৮,০০০ | ১,০০০ | - | ১৯,০০০ | -\n3. আগস্ট ১৫ | মূলধন হিসাব | | ২০,০০০ | - | - | - | ২০,০০০\n4. আগস্ট ২২ | আসবাবপত্র | | ১০,০০০ | - | - | - | ১০,০০০\n**মোট যোগফল:** নগদান ডে. ৯৮,০০০ + বাট্টা ডে. ১,০০০ = মোট ডেবিট ৯৯,০০০ টাকা; মোট ক্রেডিট (৫০,০০০ + ১৯,০০০ + ৩০,০০০) = ৯৯,০০০ টাকা।"
      }
