        "kha": "**নিট চলতি সম্পদ নির্ণয়:**\n- হাতে নগদ = ২০,০০০ টাকা\n- ব্যাংক জমা = ৫০,০০০ টাকা\n- দেনাদার (৬০,০০০ - ৫% সঞ্চিতি ৩,০০০) = ৫৭,০০০ টাকা\n- সমাপনী মজুদ পণ্য = ৪০,০০০ টাকা\n**মোট চলতি সম্পদ = ১,৬৭,০০০ টাকা**।\n- বাদ: চলতি দায় (পাওনাদার) = (৪৫,০০০) টাকা\n**নিট চলতি সম্পদ (Working Capital) = ১,২২,০০০ টাকা**।",
