      "stem": "'বৈশাখী বেকারি' ২০২৪ সালের জানুয়ারি মাসে ৫,০০০ প্যাকেট বিস্কুট তৈরি করে। তাদের ব্যয়ের তথ্য:\nময়দা ও চিনি ক্রয় ৬০,০০০ টাকা, বেকারি কারিগরদের মজুরি ২০,০০০ টাকা, কারখানার জ্বালানি ও গ্যাস ৫,০০০ টাকা, কারখানার বিদ্যুৎ খরচ ৩,০০০ টাকা, প্যাকেজিং খরচ ২,০০০ টাকা, অফিস বেতন ৮,০০০ টাকা, শোরুম ভাড়া ৪,০০০ টাকা।",
