        "kha": "**১. মুখ্য ব্যয়:**\n- ময়দা ও চিনি (প্রত্যক্ষ কাঁচামাল) = ৬০,০০০ টাকা\n- প্রত্যক্ষ মজুরি = ২০,০০০ টাকা\n**মুখ্য ব্যয় = ৮০,০০০ টাকা**।\n\n**২. কারখানা উপরিব্যয়:**\n- কারখানার গ্যাস ও জ্বালানি = ৫,০০০ টাকা\n- কারখানার বিদ্যুৎ খরচ = ৩,০০০ টাকা\n- মোট কারখানা উপরিখরচ = ৮,০০০ টাকা।\n**কারখানা ব্যয় = মুখ্য ব্যয় ৮০,০০০ + কারখানা উপরিখরচ ৮,০০০ = ৮৮,০০০ টাকা**।",
