        "kha": "**মোট ব্যয় নির্ণয়:**\n- কারখানা/উৎপাদন ব্যয় = ২,৫০,০০০ টাকা\n- যোগ: প্রশাসনিক খরচ = ২০,০০০ টাকা\n- যোগ: বিক্রয় ও বিতরণ খরচ = ৩০,০০০ টাকা\n**মোট ব্যয় = ৩,০০,০০০ টাকা**।",
        "ga": "**বিক্রয়মূল্য নির্ধারণ:**\n- মোট ব্যয় = ৩,০০,০০০ টাকা\n- যোগ: প্রত্যাশিত মুনাফা (৩,০০,০০০ × ২০%) = ৬০,০০০ টাকা\n- **মোট বিক্রয়মূল্য = ৩,৬০,০০০ টাকা**।\n\nমোট আলমারি = ১০০টি।\n**প্রতিটি আলমারির বিক্রয়মূল্য = ৩,৬০,০০০ ÷ ১০০ = ৩,৬০০ টাকা**।"
