      "title": "'মেঘনা ফার্নিচার' (কাঠের টেবিল তৈরির একক ব্যয়)",
      "stem": "'মেঘনা ফার্নিচার' ৫০টি পড়ার টেবিল তৈরি করে। কাঠ ক্রয় ৫০,০০০ টাকা, কাঠ পরিবহন ১,০০০ টাকা, কাঠমিস্ত্রির মজুরি ১৫,০০০ টাকা, বার্নিশ ও পেরেক ক্রয় ২,০০০ টাকা, কারখানা ভাড়া ৫,০০০ টাকা, বিক্রয়কর্মীর কমিশন ৩,০০০ টাকা। বিক্রয়মূল্যের ওপর ২০% লাভে টেবিলগুলো বিক্রি করা হয়।",
      "ka": "বিক্রয়মূল্যের ওপর ২০% লাভ হলে ব্যয়ের ওপর লাভের হার কত?",
      "kha": "টেবিল তৈরির মোট উৎপাদন ব্যয় এবং একক প্রতি উৎপাদন ব্যয় নির্ণয় করো।",
      "ga": "বিক্রয়মূল্যের ওপর ২০% লাভে ৫০টি টেবিলের মোট বিক্রয়মূল্য নির্ণয় করো।",
      "solution": {
        "ka": "বিক্রয়মূল্যের ওপর ২০% লাভ হলে ব্যয়ের ওপর লাভের হার হবে **২৫%** (সূত্র: ২০ ÷ (১০০-২০) × ১০০ = ২৫%)।",
        "kha": "**উৎপাদন ব্যয় নির্ণয়:**\n- প্রত্যক্ষ কাঁচামাল (কাঠ ৫০,০০০ + পরিবহন ১,০০০) = ৫১,০০০ টাকা\n- প্রত্যক্ষ মজুরি = ১৫,০০০ টাকা\n- মুখ্য ব্যয় = ৬৬,০০০ টাকা।\n- যোগ: কারখানা উপরিখরচ (বার্নিশ ২,০০০ + কারখানা ভাড়া ৫,০০০) = ৭,০০০ টাকা\n**মোট উৎপাদন ব্যয় = ৭৩,০০০ টাকা**।\n**একক প্রতি উৎপাদন ব্যয় = ৭৩,০০০ ÷ ৫০ = ১,৪৬০ টাকা**।",
        "ga": "**মোট বিক্রয়মূল্য নির্ণয়:**\n- মোট উৎপাদন ব্যয় = ৭৩,০০০ টাকা\n- যোগ: বিক্রয় কমিশন = ৩,০০০ টাকা\n- মোট ব্যয় = ৭৬,০০০ টাকা।\n- যোগ: মুনাফা (ব্যয়ের ওপর ২৫% = ৭৬,০০০ × ২৫%) = ১৯,০০০ টাকা\n**মোট বিক্রয়মূল্য = ৯৫,০০০ টাকা** (প্রতিটি টেবিল ১,৯০০ টাকা)।"
      }
